<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Returns | Digital Library</title><link rel="stylesheet" href="/assets/app.css"></head><body><header class="site-header"><a class="brand" href="/dashboard">Digital Library</a><nav><a href="/">Catalog</a></nav></header><main class="container"><p class="eyebrow">Circulation desk</p><h1>Returns</h1><?php if ($error): ?><p class="form-error" role="alert"><?= e($error) ?></p><?php endif; ?><?php if ($success): ?><p class="form-success" role="status"><?= e($success) ?></p><?php endif; ?><div class="book-grid"><?php foreach ($loans as $loan): ?><article class="book-card"><h2><?= e($loan['title']) ?></h2><p><?= e($loan['member_name']) ?> · <?= e($loan['accession_number']) ?></p><p class="muted">Due <?= e($loan['due_at']) ?></p><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="loan_id" value="<?= e((string) $loan['id']) ?>"><button type="submit">Process return</button></form></article><?php endforeach; ?></div></main></body></html>